import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readPageFile(e){return readFileSync(resolve(__dirname,"../../frontend/nao-sena-medal-explorer",e),"utf-8")}function readLandingFile(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Nao Sena Medal Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readPageFile("index.html")}),it("contains hero title and badges",()=>{expect(e).toContain('class="nsm-hero-title"'),expect(e).toContain("Nao Sena Medal Explorer"),expect(e).toContain("Instituted:"),expect(e).toContain("1960")}),it("contains all required content sections",()=>{["history","eligibility","medal-design","naval-operations","selection","awardees","timeline","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains naval operations content",()=>{expect(e).toContain("Operation Trident"),expect(e).toContain("INS Khukri"),expect(e).toContain("Anti-Piracy Operations")}),it("contains search filter for awardees timeline",()=>{expect(e).toContain('id="recipient-search"'),expect(e).toContain('id="recipients-tbody"')}),it("contains timeline and image gallery",()=>{expect(e).toContain('class="timeline-list"'),expect(e).toContain('class="gallery-grid"')}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Nao Sena Medal Explorer — Assets & Script",()=>{it("includes a non-empty stylesheet",()=>{const e=readPageFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".nsm-hero")}),it("includes valid interactive script",()=>{const e=readPageFile("script.js");expect(e).toContain("initTabs"),expect(e).toContain("initRecipientSearch")})}),describe("Nao Sena Medal Explorer — Landing Page Integration",()=>{it("is linked on the Awards of India Explorer Landing Page",()=>{const e=readLandingFile();expect(e).toContain("Nao Sena Medal"),expect(e).toContain("../nao-sena-medal-explorer/index.html")})});